function htmlScaffold(): Scaffold[] {
  return [
    {
      path: "frontend/css/base.css",
      description: "Reset and base styles",
      task: "frontend_file",
      content: `*,*::before,*::after{box-sizing:border-box}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;line-height:1.5;color:#0f172a;background:#f8fafc}
img{max-width:100%;display:block}
a{color:inherit}
.container{max-width:1100px;margin:0 auto;padding:0 1.25rem}
.btn{display:inline-flex;align-items:center;gap:.5rem;padding:.6rem 1.1rem;border-radius:.5rem;border:0;background:#0f172a;color:#fff;cursor:pointer;font-weight:500}
.btn:hover{background:#1e293b}
.card{background:#fff;border:1px solid #e2e8f0;border-radius:.75rem;padding:1.25rem}
input,textarea,select{font:inherit;padding:.55rem .75rem;border:1px solid #cbd5e1;border-radius:.5rem;width:100%}
`,
    },
    {
      path: "frontend/js/api.js",
      description: "Fetch helper for the backend API",
      task: "frontend_file",
      content: `const API_URL = window.API_URL || "http://localhost:8000";

export async function api(path, options = {}) {
  const res = await fetch(API_URL + path, {
    headers: { "Content-Type": "application/json", ...(options.headers || {}) },
    ...options,
    body: options.body && typeof options.body !== "string" ? JSON.stringify(options.body) : options.body,
  });
  if (!res.ok) throw new Error((await res.text()) || res.statusText);
  return res.status === 204 ? null : res.json();
}
`,
    },
  ];
}

function expressScaffold(db: string): Scaffold[] {
  const dbDeps: Record<string, Record<string, string>> = {
    postgres: { pg: "^8.13.0" },
    supabase: { "@supabase/supabase-js": "^2.45.4" },
    mongodb: { mongoose: "^8.6.3" },
  };
  const dbFile: Record<string, string> = {
    postgres: `import pg from "pg";

export const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });

export async function query(text, params) {
  const result = await pool.query(text, params);
  return result.rows;
}
`,
    supabase: `import { createClient } from "@supabase/supabase-js";

export const supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY, {
  auth: { persistSession: false },
});
`,
    mongodb: `import mongoose from "mongoose";

export async function connectDb() {
  await mongoose.connect(process.env.MONGODB_URI);
  console.log("MongoDB connected");
}
`,
  };
  return [
    {
      path: "server/package.json",
      description: "Backend dependencies and scripts",
      task: "config_file",
      content: j({
        name: "server",
        private: true,
        type: "module",
        scripts: { dev: "node --watch --env-file=.env src/index.js", start: "node src/index.js" },
        dependencies: {
          express: "^4.21.0",
          cors: "^2.8.5",
          helmet: "^7.1.0",
          zod: "^3.23.8",
          jsonwebtoken: "^9.0.2",
          ...dbDeps[db],
        },
      }),
    },
    { path: "server/src/db.js", description: "Database client", task: "backend_file", content: dbFile[db] ?? "" },
    {
      path: "server/src/middleware/error.js",
      description: "Central error handler",
      task: "backend_file",
      content: `export function notFound(req, res) {
  res.status(404).json({ error: "Not found" });
}

export function errorHandler(err, req, res, _next) {
  console.error(err);
  const status = err.status || 500;
  res.status(status).json({ error: status === 500 ? "Internal server error" : err.message });
}
`,
    },
  ];
}

function fastapiScaffold(db: string): Scaffold[] {
  const dbReq: Record<string, string> = {
    postgres: "asyncpg==0.29.0\n",
    supabase: "supabase==2.7.4\n",
    mongodb: "motor==3.6.0\nbeanie==1.26.0\n",
  };
  const dbFile: Record<string, string> = {
    postgres: `import os
import asyncpg

pool: asyncpg.Pool | None = None


async def connect() -> None:
    global pool
    pool = await asyncpg.create_pool(os.environ["DATABASE_URL"])


async def disconnect() -> None:
    if pool:
        await pool.close()
`,
    supabase: `import os
from supabase import create_client, Client

supabase: Client = create_client(os.environ["SUPABASE_URL"], os.environ["SUPABASE_SERVICE_ROLE_KEY"])


async def connect() -> None:
    return None


async def disconnect() -> None:
    return None
`,
    mongodb: `import os
from motor.motor_asyncio import AsyncIOMotorClient

client: AsyncIOMotorClient | None = None


async def connect() -> None:
    global client
    client = AsyncIOMotorClient(os.environ["MONGODB_URI"])


async def disconnect() -> None:
    if client:
        client.close()
`,
  };
  return [
    {
      path: "server/requirements.txt",
      description: "Python dependencies",
      task: "config_file",
      content: `fastapi==0.115.0\nuvicorn[standard]==0.30.6\npydantic==2.9.2\npython-dotenv==1.0.1\npython-jose[cryptography]==3.3.0\n${dbReq[db] ?? ""}`,
    },
    { path: "server/app/db.py", description: "Database connection", task: "backend_file", content: dbFile[db] ?? "" },
  ];
}

export function scaffoldFor(stack: StackOption): Scaffold[] {
  const fe =
    stack.frontendId === "nextjs" ? nextScaffold() : stack.frontendId === "html" ? htmlScaffold() : reactScaffold();
  const be = stack.backendId === "fastapi" ? fastapiScaffold(stack.databaseId) : expressScaffold(stack.databaseId);
  return [...fe, ...be];
}

/** Adds scaffold files to a plan manifest, replacing any model-planned duplicates. */
export function mergeScaffold(files: PlanFile[], stack: StackOption): PlanFile[] {
  const scaffold = scaffoldFor(stack);
  const paths = new Set(scaffold.map((s) => s.path));
  return [
    ...scaffold.map(({ path, description, task }) => ({ path, description, task })),
    ...files.filter((f) => !paths.has(f.path)),
  ];
}

/** Short summary injected into prompts so generated code reuses the scaffold. */
export function scaffoldSummary(stack: StackOption): string {
  return scaffoldFor(stack)
    .map((s) => `- ${s.path}: ${s.description}`)
    .join("\n");
}
